(function(){
  function toggleShow(element, force) {
    if (!element) return;
    const willShow = typeof force === 'boolean' ? force : !element.classList.contains('show');
    element.classList.toggle('show', willShow);
    const button = document.querySelector('[data-bs-target="#' + element.id + '"]');
    if (button) {
      button.classList.toggle('collapsed', !willShow);
      button.setAttribute('aria-expanded', String(willShow));
    }
  }

  function bindCollapseButtons() {
    document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(function(button) {
      if (button.dataset.bound === 'true') return;
      button.dataset.bound = 'true';
      button.addEventListener('click', function(event) {
        event.preventDefault();
        const selector = button.getAttribute('data-bs-target');
        if (!selector) return;
        const target = document.querySelector(selector);
        if (!target) return;
        const isOpen = target.classList.contains('show');
        toggleShow(target, !isOpen);
      });
    });
  }

  function bindAccordionButtons() {
    document.querySelectorAll('.accordion-button').forEach(function(button) {
      if (button.dataset.bound === 'true') return;
      button.dataset.bound = 'true';
      button.addEventListener('click', function(event) {
        event.preventDefault();
        const targetSelector = button.getAttribute('data-bs-target');
        const target = targetSelector ? document.querySelector(targetSelector) : null;
        if (!target) return;
        const isOpen = target.classList.contains('show');
        document.querySelectorAll('.accordion-collapse').forEach(function(item) {
          if (item !== target) {
            item.classList.remove('show');
            const control = document.querySelector('[data-bs-target="#' + item.id + '"]');
            if (control) {
              control.classList.add('collapsed');
              control.setAttribute('aria-expanded', 'false');
            }
          }
        });
        toggleShow(target, !isOpen);
      });
    });
  }

  document.addEventListener('DOMContentLoaded', function() {
    bindCollapseButtons();
    bindAccordionButtons();
  });
})();
